"""The two groups of order 4 (Sections 2.3 and 2.8). Left: the cyclic group Z_4, generated by 1, whose
elements have orders 1, 4, 2, 4. Right: the Klein four-group V = Z_2 x Z_2 = {e, a, b, c}, in which
every element is its own inverse (the diagonal is all e) and the product of any two non-identity
elements is the third. Since Z_4 has an element of order 4 and V does not, they are not isomorphic."""

import matplotlib.pyplot as plt


def table(ax, elems, op, title):
    for i, x in enumerate(elems):
        for j, y in enumerate(elems):
            z = op(i, j)
            ax.add_patch(plt.Rectangle((j, -i), 1, 1, fc=f"C{z}", alpha=0.32, ec="0.6", lw=0.6))
            ax.text(j + 0.5, -i + 0.5, f"${elems[z]}$", ha="center", va="center", fontsize=14)
        ax.text(-0.4, -i + 0.5, f"${x}$", ha="center", va="center", fontsize=14)
        ax.text(i + 0.5, 1.35, f"${x}$", ha="center", va="center", fontsize=14)
    ax.set_title(title, fontsize=13, pad=14)
    ax.set_xlim(-0.8, 4.05); ax.set_ylim(-3.05, 1.8); ax.set_aspect("equal"); ax.axis("off")


fig, (a, b) = plt.subplots(1, 2, figsize=(9.2, 4.6))
table(a, ["0", "1", "2", "3"], lambda i, j: (i + j) % 4, r"$\mathbb{Z}_4$")
table(b, ["e", "a", "b", "c"], lambda i, j: i ^ j, r"$V = \mathbb{Z}_2 \times \mathbb{Z}_2$")
